Rules.InvariantScript:
Set(varThisWeekStart, DateAdd(Today(), -(Weekday(Today(), StartOfWeek.Monday) - 1), "Days"));

Refresh('Hours Tracking (Hours)');

ClearCollect(
    colPendingApprovalHours,
    If(
        varIsSuperAdmin,
        Filter(
            'Hours Tracking (Hours)',
            ApprovalStatus_1 = "Pending"
        ),
        Filter(
            'Hours Tracking (Hours)',
            ApproverID_1 = User().Email &&
            ApprovalStatus_1 = "Pending"
        )
    )
);

Set(
    varPendingApprovalWeeks,
    CountRows(
        Distinct(
            colPendingApprovalHours,
            Text(DateAdd(Date, -(Weekday(Date, StartOfWeek.Monday) - 1), "Days"), "yyyy-mm-dd") & Employee_Name
        )
    )
);

ClearCollect(
    colMyHours,
    Filter(
        'Hours Tracking (Hours)',
        Employee = User().Email &&
        Date >= varAppStartDate
    )
);

ClearCollect(
    colMissingWeeks,
    ForAll(
        Sequence(
            RoundDown(
                DateDiff(
                    DateAdd(varAppStartDate, -(Weekday(varAppStartDate, StartOfWeek.Monday) - 1), "Days"),
                    varThisWeekStart,
                    "Days"
                ) / 7,
                0
            ) + 1,
            0,
            1
        ),
        With(
            {
                weekStart: DateAdd(
                    DateAdd(varAppStartDate, -(Weekday(varAppStartDate, StartOfWeek.Monday) - 1), "Days"),
                    Value * 7,
                    "Days"
                )
            },
            If(
                weekStart <= varThisWeekStart &&
                CountRows(
                    Distinct(
                        Filter(
                            colMyHours,
                            Date >= weekStart &&
                            Date <= DateAdd(weekStart, 4, "Days") &&
                            (
                                ApprovalStatus_1 = "Pending" ||
                                ApprovalStatus_1 = "Approved"
                            )
                        ),
                        Text(Date, "yyyy-mm-dd")
                    )
                ) < 5,
                {
                    WeekStart: weekStart,
                    WeekEnd: DateAdd(weekStart, 6, "Days"),
                    WeekLabel: Text(weekStart, "mmm d") & " - " & Text(DateAdd(weekStart, 6, "Days"), "mmm d, yyyy")
                }
            )
        )
    )
);

Set(varCurrentWeekStart, ThisItem.WeekStart);
Set(varDrillFromWeekly, false);
Navigate('Hours Tracking', ScreenTransition.Cover);
